-- ============================================================
-- STOCK COUNT CONFIG — productos a contar por sector
-- ============================================================

BEGIN;

-- Limpiar config anterior si existe
TRUNCATE operations.stock_count_config RESTART IDENTITY;


-- Verificación
SELECT s.name AS sector, COUNT(*) AS productos
FROM operations.stock_count_config scc
JOIN core.sectors s ON s.id = scc.sector_id
WHERE scc.is_active = TRUE
GROUP BY s.name ORDER BY s.name;

COMMIT;